fn copy_wildcard_pattern(c: &mut AstCopier<'_>, slot: usize) -> NodeId {
    let mut node = c.src.stores.wildcard_pattern[slot].clone();
    node.keyword = node.keyword.map(|t| c.token(t));
    node.type_ = node.type_.map(|n| c.node(n));
    node.name = c.token(node.name);
    c.dst.add(node).raw()
}

#[inline(never)]
fn copy_with_clause(c: &mut AstCopier<'_>, slot: usize) -> NodeId {
    let mut node = c.src.stores.with_clause[slot].clone();
    node.with_keyword = c.token(node.with_keyword);
    node.mixin_types = c.list(node.mixin_types);
    c.dst.add(node).raw()
}

#[inline(never)]
fn copy_yield_statement(c: &mut AstCopier<'_>, slot: usize) -> NodeId {
    let mut node = c.src.stores.yield_statement[slot].clone();
    node.yield_keyword = c.token(node.yield_keyword);
    node.star = node.star.map(|t| c.token(t));
    node.expression = c.node(node.expression);
    node.semicolon = c.token(node.semicolon);
    c.dst.add(node).raw()
}
